import { createHash, createHmac, randomBytes } from "node:crypto";
import { AsyncLocalStorage } from "node:async_hooks";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { chmod, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import { Credential } from "mppx";

const PAYMENT_HEADERS = ["payment-signature", "x-payment", "x-payment-signature"];
const settlementContext = new AsyncLocalStorage();

export const MCP_RECOVERY_TOOL = "recover_paid_result";
export const MCP_RECOVERY_META = "samedaydesk/recovery";

// The useful payload has its own lineage; payment/delivery signatures are not
// a usefulness verdict and may acquire transport metadata after this boundary.
export function mcpRecoveryResultDigest(result) {
  return createHash("sha256").update(JSON.stringify({
    content: result?.content,
    structuredContent: result?.structuredContent ?? null,
    isError: result?.isError === true,
  })).digest("hex");
}

// Observe the existing facilitator call, without replacing either payment rail.
// The possible-spend marker is durable BEFORE the external mutation begins.
export function trackReplaySettlementAttempts(client) {
  return new Proxy(client, {
    get(target, key) {
      if (key === "settle") return async (...args) => {
        await settlementContext.getStore()?.();
        return target.settle(...args);
      };
      const value = Reflect.get(target, key, target);
      return typeof value === "function" ? value.bind(target) : value;
    },
  });
}

export function replaySettlementWasAttempted() {
  return settlementContext.getStore()?.attempted === true;
}

function persistentReplaySecret(dataDir) {
  mkdirSync(dataDir, { recursive: true, mode: 0o700 });
  const file = path.join(dataDir, "idempotency-replay.key");
  try { writeFileSync(file, randomBytes(32).toString("hex"), { flag: "wx", mode: 0o600 }); }
  catch (error) { if (error.code !== "EEXIST") throw error; }
  const key = readFileSync(file, "utf8").trim();
  if (!/^[a-f0-9]{64}$/.test(key)) throw new Error("invalid persisted replay key");
  return key;
}
const PAYMENT_ID_PATTERN = /^[A-Za-z0-9_-]{16,128}$/;
const EVM_ADDRESS_PATTERN = /^0x[0-9a-fA-F]{40}$/;
const SAFE_REPLAY_HEADERS = new Set([
  "content-type",
  "payment-response",
  "payment-receipt",
  "x-payment-response",
  "x-payment-receipt",
]);

export const DEFAULT_PAID_ROUTES = new Set([
  "/extract",
  "/read",
  "/scan",
  "/schemaforge",
  "/enrich",
  "/wallet-enrich",
  "/deep-audit",
  "/defi/morpho-position",
  "/defi/morpho-protection",
  "/defi/morpho-market-underwrite",
  "/defi/morpho-preliquidation-replay",
  "/work/opportunity-preflight",
  "/distribution/agent-discoverability-audit",
  "/commerce/payment-offer-preflight",
  "/commerce/settlement-proof",
  "/chain/transaction-receipt",
  "/chain/solana-transaction-receipt",
  "/security/wallet-policy-conformance",
  "/security/stateful-wallet-policy-conformance",
]);

function headerValue(headers, name) {
  const value = headers?.[name] ?? headers?.[name.toLowerCase()];
  return Array.isArray(value) ? value.join(",") : String(value || "");
}

function x402PaymentHeader(headers) {
  return PAYMENT_HEADERS.map((name) => headerValue(headers, name)).find(Boolean) || "";
}

function mppPaymentHeader(headers) {
  return Credential.extractPaymentScheme(headerValue(headers, "authorization")) || "";
}

function normalizeAddress(value) {
  const candidate = String(value || "");
  return EVM_ADDRESS_PATTERN.test(candidate) ? candidate.toLowerCase() : null;
}

export function canonicalReplayUrl(value) {
  const url = new URL(value);
  url.hash = "";
  const entries = [...url.searchParams.entries()].sort(([leftKey, leftValue], [rightKey, rightValue]) =>
    leftKey.localeCompare(rightKey) || leftValue.localeCompare(rightValue));
  url.search = "";
  for (const [key, entryValue] of entries) url.searchParams.append(key, entryValue);
  return url.toString();
}

export function decodeReplayPayment(headers) {
  const encoded = x402PaymentHeader(headers);
  if (encoded) {
    try {
      const payment = JSON.parse(Buffer.from(encoded.trim(), "base64").toString("utf8"));
      const suppliedId = payment?.extensions?.["payment-identifier"]?.info?.id;
      const id = suppliedId == null ? createHash("sha256").update(encoded.trim()).digest("hex") : suppliedId;
      const payer = normalizeAddress(payment?.payload?.authorization?.from || payment?.payload?.from);
      const accepted = payment?.accepted;
      if (!PAYMENT_ID_PATTERN.test(String(id || "")) || !payer || payment?.x402Version !== 2) return null;
      if (!accepted || typeof accepted !== "object") return null;
      const terms = {
        scheme: String(accepted.scheme || ""),
        network: String(accepted.network || ""),
        asset: normalizeAddress(accepted.asset),
        amount: String(accepted.amount || ""),
        payTo: normalizeAddress(accepted.payTo),
      };
      if (terms.scheme !== "exact" || !terms.network || !terms.asset || !/^\d+$/.test(terms.amount) || !terms.payTo) {
        return null;
      }
      return {
        id: String(id),
        hasPaymentIdentifier: suppliedId != null,
        payer,
        protocol: "x402",
        credentialBinding: createHash("sha256").update(encoded.trim()).digest("hex"),
        validUntilMs: Number(payment?.payload?.authorization?.validBefore) * 1000,
        authorizationIdentity: /^0x[a-fA-F0-9]{64}$/.test(String(payment?.payload?.authorization?.nonce || ""))
          ? JSON.stringify([terms.network, terms.asset, payer, payment.payload.authorization.nonce.toLowerCase()]) : null,
        terms,
      };
    } catch {
      return null;
    }
  }

  const authorization = mppPaymentHeader(headers);
  if (!authorization) return null;
  try {
    const credential = Credential.deserialize(authorization);
    const request = credential?.challenge?.request;
    const details = request?.methodDetails;
    const payer = normalizeAddress(credential?.payload?.from);
    const payTo = normalizeAddress(request?.recipient);
    const asset = normalizeAddress(request?.currency);
    const amount = String(request?.amount || "");
    const chainId = Number(details?.chainId);
    if (credential?.challenge?.method !== "evm" || credential?.challenge?.intent !== "charge") return null;
    if (!payer || !payTo || !asset || !/^\d+$/.test(amount) || !Number.isSafeInteger(chainId) || chainId <= 0) {
      return null;
    }
    if (normalizeAddress(credential?.payload?.to) !== payTo || String(credential?.payload?.value || "") !== amount) {
      return null;
    }
    return {
      id: createHash("sha256").update(authorization).digest("hex"),
      payer,
      protocol: "mpp",
      credentialBinding: createHash("sha256").update(authorization).digest("hex"),
      validUntilMs: Number(credential?.payload?.validBefore) * 1000,
      terms: {
        scheme: "evm-charge",
        network: `eip155:${chainId}`,
        asset,
        amount,
        payTo,
      },
    };
  } catch {
    return null;
  }
}

function publicRequestUrl(req) {
  const forwardedProto = headerValue(req.headers, "x-forwarded-proto").split(",", 1)[0].trim();
  const protocol = forwardedProto || req.protocol || "https";
  const host = headerValue(req.headers, "x-forwarded-host").split(",", 1)[0].trim()
    || headerValue(req.headers, "host")
    || "localhost";
  return canonicalReplayUrl(`${protocol}://${host}${req.originalUrl || req.url || req.path || "/"}`);
}

function boundedInteger(value, fallback, minimum, maximum) {
  const candidate = Number(value);
  return Number.isInteger(candidate) && candidate >= minimum && candidate <= maximum ? candidate : fallback;
}

async function readStore(filePath) {
  try {
    const parsed = JSON.parse(await readFile(filePath, "utf8"));
    if (parsed?.v !== 1 || !Array.isArray(parsed.records)) throw new Error("invalid replay store");
    return parsed.records;
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }
}

export function createIdempotencyReplay({
  dataDir = process.env.COMMERCE_DATA_DIR || path.join(process.cwd(), "data"),
  secret = process.env.COMMERCE_ACTOR_SECRET,
  ttlMs = boundedInteger(process.env.IDEMPOTENCY_TTL_MS, 15 * 60_000, 60_000, 24 * 60 * 60_000),
  maxEntries = boundedInteger(process.env.IDEMPOTENCY_MAX_ENTRIES, 256, 1, 2_000),
  maxResponseBytes = boundedInteger(process.env.IDEMPOTENCY_MAX_RESPONSE_BYTES, 512 * 1024, 1_024, 2 * 1024 * 1024),
  routes = DEFAULT_PAID_ROUTES,
  inFlightPaths = routes,
  requiredReplayPaths = new Set(),
  publicUrl,
  inFlightWaitMs = boundedInteger(process.env.IDEMPOTENCY_INFLIGHT_WAIT_MS, 15_000, 50, 60_000),
  now = () => Date.now(),
} = {}) {
  const storePath = path.join(dataDir, "idempotency-replay.json");
  const tempPath = path.join(dataDir, "idempotency-replay.tmp.json");
  let queue = Promise.resolve();
  const unpersistedMcpResults = new Map();
  const replaySecret = secret || persistentReplaySecret(dataDir);

  const digest = (label, value) => createHmac("sha256", replaySecret).update(`${label}:${value}`).digest("hex");

  function bindingFor({ method, url, headers, bodyBytes }) {
    const payment = decodeReplayPayment(headers);
    if (!payment) return null;
    const requestUrl = new URL(url);
    if (publicUrl) {
      const origin = new URL(publicUrl);
      requestUrl.protocol = origin.protocol;
      requestUrl.host = origin.host;
      requestUrl.port = origin.port;
    }
    const canonicalUrl = canonicalReplayUrl(requestUrl.href);
    const normalizedMethod = String(method || "GET").toUpperCase();
    const hasRequestBody = !["GET", "HEAD"].includes(normalizedMethod);
    const requestBody = Buffer.isBuffer(bodyBytes)
      ? bodyBytes
      : Buffer.from(bodyBytes == null ? "" : String(bodyBytes));
    const material = JSON.stringify({
      v: 2,
      method: normalizedMethod,
      url: canonicalUrl,
      bodySha256: hasRequestBody ? createHash("sha256").update(requestBody).digest("hex") : null,
      payer: payment.payer,
      credentialBinding: payment.credentialBinding,
      ...payment.terms,
    });
    return {
      key: digest("payment-id", payment.id),
      credentialKey: payment.authorizationIdentity ? digest("authorization", payment.authorizationIdentity) : null,
      fingerprint: digest("request", material),
      paymentId: payment.id,
      payer: payment.payer,
      validUntilMs: payment.validUntilMs,
      protected: inFlightPaths.has(new URL(canonicalUrl).pathname),
      hasPaymentIdentifier: payment.protocol !== "x402" || payment.hasPaymentIdentifier,
    };
  }

  async function mutate(operation) {
    let result;
    queue = queue.catch(() => {}).then(async () => {
      await mkdir(dataDir, { recursive: true, mode: 0o700 });
      await chmod(dataDir, 0o700).catch(() => {});
      const currentTime = now();
      const records = (await readStore(storePath)).filter((record) => Number(record.expiresAt) > currentTime);
      const mutation = await operation(records, currentTime);
      result = mutation.result;
      const protectedRecords = mutation.records.filter((record) => record.protected);
      if (protectedRecords.length > maxEntries) throw new Error("replay capacity exhausted");
      const bounded = [...protectedRecords, ...mutation.records.filter((record) => !record.protected)
        .sort((left, right) => Number(right.createdAt) - Number(left.createdAt))
        .slice(0, maxEntries - protectedRecords.length)];
      await writeFile(tempPath, `${JSON.stringify({ v: 1, records: bounded })}\n`, { encoding: "utf8", mode: 0o600 });
      await chmod(tempPath, 0o600).catch(() => {});
      await rename(tempPath, storePath);
      await chmod(storePath, 0o600).catch(() => {});
    });
    await queue;
    return result;
  }

  async function lookup(binding) {
    if (!binding) return { kind: "miss" };
    return mutate(async (records) => {
      const existing = records.find((record) => record.key === binding.key || (binding.credentialKey && record.credentialKey === binding.credentialKey));
      if (!existing) return { records, result: { kind: "miss" } };
      if (existing.fingerprint !== binding.fingerprint) {
        return { records, result: { kind: "conflict" } };
      }
      if (existing.pending) return { records, result: { kind: "pending" } };
      return { records, result: { kind: "hit", record: existing } };
    });
  }

  async function claim(binding) {
    if (!binding) return { kind: "miss" };
    return mutate(async (records, currentTime) => {
      const existing = records.find((record) => record.key === binding.key || (binding.credentialKey && record.credentialKey === binding.credentialKey));
      if (!existing) {
        if (Number.isFinite(binding.validUntilMs) && binding.validUntilMs <= currentTime) return { records, result: { kind: "expired" } };
        if (records.filter((record) => record.protected).length >= maxEntries) return { records, result: { kind: "capacity" } };
        const record = {
          v: 1,
          key: binding.key,
          credentialKey: binding.credentialKey,
          fingerprint: binding.fingerprint,
          pending: true,
          protected: true,
          createdAt: currentTime,
          expiresAt: Math.max(currentTime + ttlMs, Number.isFinite(binding.validUntilMs) ? binding.validUntilMs + 60_000 : 0),
        };
        return { records: [record, ...records], result: { kind: "miss", reserved: true } };
      }
      if (existing.fingerprint !== binding.fingerprint) {
        return { records, result: { kind: "conflict" } };
      }
      if (existing.pending) return { records, result: { kind: "pending" } };
      return { records, result: { kind: "hit", record: existing } };
    });
  }

  async function release(binding) {
    if (!binding) return false;
    return mutate(async (records) => ({
      records: records.filter((record) => !(
        record.key === binding.key
        && record.pending
        && record.fingerprint === binding.fingerprint
      )),
      result: true,
    }));
  }

  async function store(binding, { status, headers, body }) {
    if (!binding || status < 200 || status >= 300) return false;
    const payload = Buffer.isBuffer(body) ? body : Buffer.from(body || "");
    if (!payload.length || payload.length > maxResponseBytes) return false;
    const safeHeaders = {};
    for (const [name, value] of Object.entries(headers || {})) {
      const normalized = name.toLowerCase();
      if (SAFE_REPLAY_HEADERS.has(normalized) && value != null) safeHeaders[normalized] = String(value);
    }
    if (!safeHeaders["payment-response"] && !safeHeaders["payment-receipt"] && !safeHeaders["x-payment-response"]) {
      return false;
    }
    return persistResponse(binding, { status, headers: safeHeaders, payload });
  }

  // One existing store/queue for HTTP and native MCP. The native port can also
  // retain an unpaid terminal refusal, without inventing a settlement proof.
  async function persistResponse(binding, { status, headers, payload, kind = "http" }) {
    const createdAt = now();
    const record = {
      v: 1,
      key: binding.key,
      credentialKey: binding.credentialKey,
      fingerprint: binding.fingerprint,
      protected: binding.protected === true,
      createdAt,
      expiresAt: Math.max(createdAt + ttlMs, Number.isFinite(binding.validUntilMs) ? binding.validUntilMs + 60_000 : 0),
      status,
      kind,
      headers,
      bodyBase64: payload.toString("base64"),
      bodySha256: createHash("sha256").update(payload).digest("hex"),
    };
    return mutate(async (records) => ({
      records: [record, ...records.filter((entry) => entry.key !== record.key)],
      result: true,
    }));
  }

  function mcpScope(scope) {
    const endpoint = new URL(scope?.endpointUrl);
    if (endpoint.username || endpoint.password || endpoint.search || endpoint.hash
      || endpoint.pathname !== "/mcp"
      || !(endpoint.protocol === "https:" || endpoint.protocol === "http:" && ["127.0.0.1", "[::1]"].includes(endpoint.hostname))) {
      throw new Error("invalid_mcp_recovery_endpoint");
    }
    if (typeof scope?.tenantId !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(scope.tenantId)) {
      throw new Error("invalid_mcp_recovery_tenant");
    }
    return { endpointUrl: endpoint.href, tenantId: scope.tenantId };
  }

  function mcpBinding({ name, arguments: args = {}, payment, scope }) {
    const endpoint = mcpScope(scope);
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(name || "") || payment?.resource?.url !== `mcp://tool/${name}`) return null;
    const bodyBytes = JSON.stringify({ name, arguments: args, ...endpoint });
    if (Buffer.byteLength(bodyBytes) > 64 * 1024) return null;
    const binding = bindingFor({ method: "POST", url: endpoint.endpointUrl,
      headers: { "payment-signature": Buffer.from(JSON.stringify(payment)).toString("base64") }, bodyBytes });
    return binding ? { ...binding, protected: true, scope: endpoint } : null;
  }

  function mcpFailure(error, charged = null) {
    return { isError: true, content: [{ type: "text", text: JSON.stringify({ ok: false, error, charged,
      newSettlementAttempt: false, usefulness: "unknown" }) }] };
  }

  function mcpRecovered(binding, result, { persisted = true, replayed = true } = {}) {
    return { ...result, _meta: { ...result._meta, [MCP_RECOVERY_META]: {
      version: 1, ...binding.scope, operationRef: binding.key,
      resultDigest: mcpRecoveryResultDigest(result), persisted, replayed,
      newSettlementAttempt: !replayed && result?._meta?.["x402/payment-response"]?.success === true,
      usefulness: "unknown",
    } } };
  }

  function decodeMcpRecord(binding, record) {
    if (record.kind !== "mcp") return mcpFailure("recovery_record_kind_rejected");
    const bytes = Buffer.from(record.bodyBase64 || "", "base64");
    if (!bytes.length || bytes.length > maxResponseBytes
      || createHash("sha256").update(bytes).digest("hex") !== record.bodySha256) return mcpFailure("recovery_record_integrity");
    try {
      const result = JSON.parse(bytes.toString("utf8"));
      if (!Array.isArray(result?.content)) return mcpFailure("recovery_record_integrity");
      return mcpRecovered(binding, result);
    } catch { return mcpFailure("recovery_record_integrity"); }
  }

  async function retainMcpResult(binding, result) {
    const payload = Buffer.from(JSON.stringify(result));
    // If saving fails, keep the completed execution in memory. A manual flush
    // or read can retry saving it; never re-execute to repair a persistence error.
    unpersistedMcpResults.set(binding.key, { binding, result });
    try {
      if (payload.length > maxResponseBytes) throw new Error("mcp_result_exceeds_replay_bounds");
      await persistResponse(binding, { status: 200, headers: {}, payload, kind: "mcp" });
      unpersistedMcpResults.delete(binding.key);
      return mcpRecovered(binding, result, { replayed: false });
    } catch {
      return mcpRecovered(binding, result, { persisted: false, replayed: false });
    }
  }

  async function recoverMcpResult(input) {
    let binding;
    try { binding = mcpBinding(input); } catch { return mcpFailure("recovery_scope_rejected", false); }
    if (!binding) return mcpFailure("recovery_binding_rejected", false);
    const retained = unpersistedMcpResults.get(binding.key);
    if (retained && retained.binding.fingerprint !== binding.fingerprint) return mcpFailure("payment_identifier_request_conflict", false);
    if (retained) {
      const saved = await retainMcpResult(binding, retained.result);
      saved._meta[MCP_RECOVERY_META].replayed = true;
      saved._meta[MCP_RECOVERY_META].newSettlementAttempt = false;
      return saved;
    }
    try {
      // Lookup only: a missing, expired or unresolved operation is never claimed
      // or executed by recovery, even if a caller still holds a valid credential.
      const cached = await lookup(binding);
      if (cached.kind === "hit") return decodeMcpRecord(binding, cached.record);
      if (cached.kind === "conflict") return mcpFailure("payment_identifier_request_conflict", false);
      return mcpFailure(cached.kind === "pending" ? "payment_execution_in_flight_or_unknown" : "recovery_not_found_or_expired");
    } catch { return mcpFailure("recovery_storage_unavailable"); }
  }

  async function runMcpTool(input, execute) {
    let binding;
    try { binding = mcpBinding(input); } catch { return mcpFailure("recovery_scope_rejected", false); }
    // Unpaid discovery remains the official wrapper's responsibility. A supplied
    // malformed paid binding is refused before an effect rather than bypassing it.
    if (!input.payment) return execute();
    if (!binding) return mcpFailure("recovery_binding_rejected", false);
    if (!Number.isFinite(binding.validUntilMs) || binding.validUntilMs > now() + ttlMs) {
      return mcpFailure("bounded_payment_validity_required", false);
    }
    let cached;
    try { cached = await claim(binding); } catch { return mcpFailure("recovery_storage_unavailable", false); }
    if (cached.kind === "hit") return decodeMcpRecord(binding, cached.record);
    if (cached.kind === "conflict") return mcpFailure("payment_identifier_request_conflict", false);
    if (cached.kind === "pending") return recoverMcpResult(input);
    if (cached.kind === "expired" || cached.kind === "capacity") return mcpFailure(`payment_replay_${cached.kind}`, false);
    let attempted = false;
    const markAttempt = async () => {
      if (attempted) return;
      await mutate(async records => ({ records: records.map(record => record.key === binding.key
        && record.fingerprint === binding.fingerprint ? { ...record, settlementAttempted: true } : record), result: true }));
      attempted = true;
      markAttempt.attempted = true;
    };
    let result;
    try { result = await settlementContext.run(markAttempt, execute); }
    catch {
      if (!attempted) await release(binding).catch(() => {});
      return mcpFailure("paid_mcp_outcome_unresolved", attempted ? null : false);
    }
    const proof = result?._meta?.["x402/payment-response"];
    const challenge = result?.structuredContent?.x402Version === 2 && Array.isArray(result.structuredContent.accepts);
    if (proof?.success === true || !attempted && !challenge && result?.isError === true) {
      return retainMcpResult(binding, result);
    }
    if (!attempted) await release(binding).catch(() => {});
    // A failed settlement response or cancellation acknowledgement cannot release
    // possible spend. The pending journal entry stays quarantined across restart.
    return result;
  }

  async function storageStatus() {
    return mutate(async (records) => ({
      records,
      result: {
        ready: true,
        activeEntries: records.length,
        ttlSeconds: Math.floor(ttlMs / 1_000),
        maxEntries,
        maxResponseBytes,
        privacy: "HMAC-bound payment IDs and request fingerprints; response bodies expire and storage is mode 0600",
      },
    })).catch(() => ({
      ready: false,
      activeEntries: null,
      ttlSeconds: Math.floor(ttlMs / 1_000),
      maxEntries,
      maxResponseBytes,
    }));
  }

  const publicProfile = Object.freeze({
    ttlSeconds: Math.floor(ttlMs / 1_000),
    mismatchStatus: 409,
    requestBinding: Object.freeze([
      "method",
      "canonical_url",
      "exact_raw_body_sha256",
      "payer",
      "payment_terms",
      "exact_settled_credential",
    ]),
  });

  async function middleware(req, res, next) {
    if (!routes.has(req.path)) return next();
    const binding = bindingFor({
      method: req.method,
      url: publicRequestUrl(req),
      headers: req.headers,
      bodyBytes: req.rawBody,
    });
    if (!binding) {
      if (requiredReplayPaths.has(req.path) && (x402PaymentHeader(req.headers) || mppPaymentHeader(req.headers))) {
        return res.status(400).json({ ok: false, error: "replayable_payment_credential_required", charged: false });
      }
      return next();
    }

    const useInFlight = inFlightPaths.has(req.path);
    // Batch (and any requiredReplayPaths route) needs an explicit x402 payment-identifier
    // for durable replay. MPP bindings set hasPaymentIdentifier via non-x402 protocol.
    // Keep expiry/TTL as a separate classification from a missing identifier.
    if (requiredReplayPaths.has(req.path) && !binding.hasPaymentIdentifier) {
      return res.status(400).json({ ok: false, error: "payment_identifier_required", charged: false });
    }
    if (requiredReplayPaths.has(req.path) && (!Number.isFinite(binding.validUntilMs) || binding.validUntilMs > now() + ttlMs)) {
      return res.status(400).json({ ok: false, error: "bounded_payment_validity_required", charged: false });
    }
    let cached = useInFlight ? await claim(binding) : await lookup(binding);
    if (cached.kind === "expired" || cached.kind === "capacity") {
      return res.status(cached.kind === "expired" ? 409 : 503).json({ ok: false, error: `payment_replay_${cached.kind}`, charged: false });
    }
    if (cached.kind === "pending") {
      const deadline = Date.now() + inFlightWaitMs;
      while (Date.now() < deadline) {
        await new Promise((resolve) => setTimeout(resolve, 25));
        cached = await lookup(binding);
        if (cached.kind !== "pending") break;
      }
      if (cached.kind === "pending" || cached.kind === "miss") {
        res.set("Cache-Control", "no-store");
        res.set("X-Payment-Idempotency", "in_flight");
        return res.status(503).json({
          ok: false,
          error: "payment_execution_in_flight_or_unknown",
          charged: null,
          newSettlementAttempt: false,
          boundary: "Matching execution is active or unresolved. This request did not settle or fetch again. Reconcile the original attempt; do not create a replacement payment automatically.",
        });
      }
    }
    if (cached.kind === "conflict") {
      res.set("Cache-Control", "no-store");
      res.set("X-Payment-Idempotency", "conflict");
      return res.status(409).json({
        ok: false,
        error: "payment_identifier_request_conflict",
        charged: false,
        boundary: "The payment identifier is already bound to a different canonical request, payer, or payment term.",
      });
    }
    if (cached.kind === "hit") {
      for (const [name, value] of Object.entries(cached.record.headers || {})) res.set(name, value);
      res.set("Cache-Control", "no-store");
      res.set("X-Payment-Replay", "hit");
      res.set("X-Payment-Idempotency", "replay");
      return res.status(cached.record.status).send(Buffer.from(cached.record.bodyBase64, "base64"));
    }

    const chunks = [];
    let settlementAttempted = false;
    const markSettlementAttempt = async () => {
      if (!cached.reserved) return;
      settlementAttempted = true;
      markSettlementAttempt.attempted = true;
      await mutate(async (records) => ({
        records: records.map((record) => record.key === binding.key && record.fingerprint === binding.fingerprint
          ? { ...record, settlementAttempted: true } : record),
        result: true,
      }));
    };
    let capturedBytes = 0;
    let overflow = false;
    const originalWrite = res.write.bind(res);
    const originalEnd = res.end.bind(res);
    const capture = (chunk, encoding) => {
      if (chunk == null || overflow) return;
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, typeof encoding === "string" ? encoding : undefined);
      capturedBytes += buffer.length;
      if (capturedBytes > maxResponseBytes) {
        overflow = true;
        chunks.length = 0;
      } else {
        chunks.push(buffer);
      }
    };
    res.write = function(chunk, encoding, callback) {
      capture(chunk, encoding);
      return originalWrite(chunk, encoding, callback);
    };
    let endScheduled = false;
    res.end = function(chunk, encoding, callback) {
      capture(chunk, encoding);
      const responseHeaders = res.getHeaders?.() || {};
      const hasSettlementProof = Boolean(
        responseHeaders["payment-response"]
        || responseHeaders["payment-receipt"]
        || responseHeaders["x-payment-response"],
      );
      if (endScheduled || overflow || res.statusCode < 200 || res.statusCode >= 300 || !hasSettlementProof) {
        const finish = () => originalEnd(chunk, encoding, callback);
        if (cached.reserved && !settlementAttempted && !hasSettlementProof) {
          endScheduled = true;
          void release(binding).catch(() => {}).finally(finish);
          return res;
        }
        return finish();
      }
      endScheduled = true;
      void store(binding, {
        status: res.statusCode,
        headers: responseHeaders,
        body: Buffer.concat(chunks),
      })
        .catch((error) => console.error(`idempotency replay write failed: ${error.message}`))
        .finally(() => originalEnd(chunk, encoding, callback));
      return res;
    };
    return settlementContext.run(markSettlementAttempt, () => next());
  }

  return {
    middleware,
    bindingFor,
    lookup,
    claim,
    release,
    store,
    runMcpTool,
    recoverMcpResult,
    mcpRecoveryProfile: scope => ({ version: 1, tool: MCP_RECOVERY_TOOL, ...mcpScope(scope) }),
    async flushMcpResults() {
      for (const { binding, result } of [...unpersistedMcpResults.values()]) await retainMcpResult(binding, result);
      return { pendingPersistence: unpersistedMcpResults.size };
    },
    storageStatus,
    publicProfile,
    flush: () => queue,
    storePath,
  };
}

mcp-server.mjs.source:
// mcp-server.mjs — a PAID MCP server (streamable-HTTP) that exposes the same tools
// as our HTTP x402 routes, gated by x402, so MCP-enabled agent clients (Claude
// Desktop, Cursor, Windsurf, etc.) can discover them via `tools/list` (free) and
// pay-per-call via `tools/call` (x402). This reaches a buyer pool the HTTP/x402scan/
// Bazaar channels don't: agents wired through MCP.
//
// Design:
//  - Self-contained + mountable: `mountMcp(app, { facilitatorClient, network, payTo,
//    serverInfo, tools })`. server.js owns the price constants + tool handlers; this
//    module is generic. Reuses the SAME facilitator (CDP) -> USDC settles to OUR payTo.
//  - `tools/list` is FREE (protocol-level discovery). `tools/call` is x402-gated by
//    @x402/mcp's createPaymentWrapper: a call without payment returns a JSON-RPC
//    error (-32042, SEP-1036) carrying the x402 PaymentRequired in error.data; a call
//    WITH a signed payment in _meta["x402/payment"] is verified, executed, and settled.
//  - STATELESS streamable-HTTP: a fresh McpServer + transport per POST /mcp request
//    (sessionIdGenerator: undefined). The expensive async setup (resourceServer
//    initialize + buildPaymentRequirements per tool) is done ONCE at mount time.
//  - express.json() is scoped to /mcp only, so it never touches the GET paywall routes.
//
// Verified against @x402/mcp@2.16.0 + @modelcontextprotocol/sdk@1.29.0 (June 2026).

import { AsyncLocalStorage } from "node:async_hooks";
import { request as requestHttp } from "node:http";
import express from "express";
import { z } from "zod";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { x402ResourceServer } from "@x402/core/server";
import { ExactEvmScheme } from "@x402/evm/exact/server";
import { createPaymentWrapper } from "@x402/mcp";
import { sealObservedMcpToolResult } from "./http-delivery-evidence/mcp-delivery.mjs";
import { attachMcpCallerResultFeedback, callerResultFeedbackMetaFromHeaders } from "./caller-result-feedback.mjs";
import { classifyDeclaredAgentDiscoverySource, listDeclaredAgentDiscoverySources } from "./commerce-events.mjs";
import { readExtractBatchInputRefusalCode } from "./extract-batch.mjs";
import { MCP_RECOVERY_TOOL, trackReplaySettlementAttempts } from "./idempotency-replay.mjs";
import {
  buildRegisteredCatalog,
  createMcpTypedTelemetryAttempt,
  digestIssuedOffer,
  productSkuForTool,
  resourceForTool,
} from "./mcp-typed-telemetry-producer.mjs";

const mcpTypedAttemptAls = new AsyncLocalStorage();
const mcpHttpRequestAls = new AsyncLocalStorage();

const MCP_PAYMENT_META_KEY = "x402/payment";
const MAX_PAYMENT_SIGNATURE_HEADER_BYTES = 32 * 1024;
const UNREGISTERED_SENTINEL_BINDING = Object.freeze({
  tool: "x",
  productSku: "y",
  resource: "z",
  issuedOfferDigest: "0".repeat(64),
});

export function createX402ToolMeta(accepts) {
  if (!Array.isArray(accepts) || accepts.length === 0) {
    throw new Error("MCP x402 tool metadata requires at least one payment option");
  }
  return {
    x402: {
      paymentRequired: true,
      accepts,
    },
  };
}

/**
 * Bridge x402 clients that send the signed PaymentPayload in the standard
 * PAYMENT-SIGNATURE HTTP header but fail to mirror it into MCP tools/call
 * metadata. The existing @x402/mcp wrapper remains the only verifier and
 * settlement authority. A valid-looking header only becomes untrusted input
 * to that wrapper; it never bypasses payment verification.
 */
export function injectPaymentSignatureHeader(req) {
  const body = req?.body;
  if (!body || Array.isArray(body) || body.method !== "tools/call") return false;
  if (!body.params || typeof body.params !== "object" || Array.isArray(body.params)) return false;

  const existingMeta = body.params._meta;
  if (existingMeta && typeof existingMeta === "object" && existingMeta[MCP_PAYMENT_META_KEY]) {
    return false;
  }

  const raw = req.get?.("PAYMENT-SIGNATURE");
  if (typeof raw !== "string" || raw.length === 0) return false;
  if (Buffer.byteLength(raw, "utf8") > MAX_PAYMENT_SIGNATURE_HEADER_BYTES) return false;
  if (!/^[A-Za-z0-9+/_-]+={0,2}$/.test(raw)) return false;

  let payment;
  try {
    const decoded = Buffer.from(raw, "base64");
    if (decoded.length === 0 || decoded.length > MAX_PAYMENT_SIGNATURE_HEADER_BYTES) return false;
    payment = JSON.parse(decoded.toString("utf8"));
  } catch {
    return false;
  }
  if (!payment || typeof payment !== "object" || Array.isArray(payment)) return false;
  if (!Number.isInteger(payment.x402Version) || !payment.payload || typeof payment.payload !== "object") {
    return false;
  }

  body.params._meta = {
    ...(existingMeta && typeof existingMeta === "object" && !Array.isArray(existingMeta) ? existingMeta : {}),
    [MCP_PAYMENT_META_KEY]: payment,
  };
  return true;
}

// Turn a tool's raw result object into an MCP tool result. Errors are returned as a
// clean structured ok:false payload (not thrown) so the caller always gets legible JSON.
export function asToolResult(obj, { structured = false } = {}) {
  const result = { content: [{ type: "text", text: JSON.stringify(obj) }] };
  if (structured && obj && typeof obj === "object" && !Array.isArray(obj)) {
    result.structuredContent = obj;
  }
  return result;
}

// A payment challenge is not a successful tool result. ok:true beside isError is.
export function isSuccessShapedStructuredContent(body) {
  if (!body || typeof body !== "object" || Array.isArray(body)) return false;
  if (Number.isInteger(body.x402Version) && Array.isArray(body.accepts)) return false;
  if (body.ok === false || body.success === false || body.error || body.isError === true) return false;
  return body.ok === true || body.success === true;
}

export function withoutSuccessShapedStructuredContent(result) {
  if (!result || result.isError !== true) return result;
  if (!isSuccessShapedStructuredContent(result.structuredContent)) return result;
  const next = { ...result };
  delete next.structuredContent;
  next.content = [{
    type: "text",
    text: JSON.stringify({ ok: false, error: "tool_execution_failed", charged: false }),
  }];
  return next;
}

export function unknownRegisteredToolError(body, catalog) {
  if (!isJsonRpcObject(body) || body.jsonrpc !== "2.0" || body.method !== "tools/call") return null;
  if (!jsonRpcHasId(body)) return null;
  const name = jsonRpcToolName(body);
  if (typeof name !== "string" || name.length === 0) return null;
  if (catalog?.has?.(name)) return null;
  return {
    jsonrpc: "2.0",
    id: body.id,
    error: { code: -32602, message: "Unknown tool" },
  };
}

/**
 * Modest, generic repair for clients that JSON-stringify array/object tool
 * arguments. Only parses when the live Zod field expects an array/object and
 * the supplied value is a JSON-encoded array/object string. Current scalar
 * tools remain unchanged.
 */
export function reviveJsonStructuredArgs(args, inputSchema = {}) {
  if (!args || typeof args !== "object" || Array.isArray(args)) return args;
  if (!inputSchema || typeof inputSchema !== "object" || Array.isArray(inputSchema)) return args;
  const next = { ...args };
  for (const [key, schema] of Object.entries(inputSchema)) {
    if (!(key in next)) continue;
    const value = next[key];
    if (typeof value !== "string") continue;
    const trimmed = value.trim();
    if (!(trimmed.startsWith("[") || trimmed.startsWith("{"))) continue;
    const expectsArray = Boolean(schema?._def?.typeName === "ZodArray" || schema?.constructor?.name === "ZodArray");
    const expectsObject = Boolean(schema?._def?.typeName === "ZodObject" || schema?.constructor?.name === "ZodObject");
    const unwrap = schema?._def?.typeName === "ZodOptional" || schema?._def?.typeName === "ZodDefault"
      ? schema._def.innerType
      : schema;
    const innerArray = Boolean(unwrap?._def?.typeName === "ZodArray" || unwrap?.constructor?.name === "ZodArray");
    const innerObject = Boolean(unwrap?._def?.typeName === "ZodObject" || unwrap?.constructor?.name === "ZodObject");
    if (!(expectsArray || expectsObject || innerArray || innerObject)) continue;
    try {
      const parsed = JSON.parse(trimmed);
      if ((innerArray || expectsArray) && Array.isArray(parsed)) next[key] = parsed;
      if ((innerObject || expectsObject) && parsed && typeof parsed === "object" && !Array.isArray(parsed)) next[key] = parsed;
    } catch {
      /* leave the original string for schema validation to reject */
    }
  }
  return next;
}

function withRevivedArgs(handler, inputSchema) {
  return async (args, extra) => handler(reviveJsonStructuredArgs(args, inputSchema), extra);
}

function boundedGetArguments(args, maxBytes) {
  const cap = Number.isInteger(maxBytes) && maxBytes > 0 ? maxBytes : 2048;
  if (!args || typeof args !== "object" || Array.isArray(args)) return { error: "invalid_arguments" };
  const keys = Object.keys(args);
  if (keys.length > 8) return { error: "request_arguments_too_large" };
  const params = new URLSearchParams();
  for (const key of [...keys].sort()) {
    if (!/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(key)) return { error: "invalid_arguments" };
    const value = args[key];
    if (typeof value !== "string" || value.length === 0 || value.length > 200) return { error: "invalid_arguments" };
    params.append(key, value);
  }
  const query = params.toString();
  if (Buffer.byteLength(query) > cap) return { error: "request_arguments_too_large" };
  return { query };
}

// Project only explicitly configured tools onto an existing paid HTTP route.
// The HTTP route owns admission, payment, replay and source work; do not also
// enter the MCP payment wrapper. No caller-controlled target URL is accepted.
// GET arguments are bounded scalar query keys on that fixed path. POST bodies
// stay the existing bridge.
function httpRouteToolHandler(tool, baseUrl) {
  const base = new URL(baseUrl);
  if (base.protocol !== "http:" || !["127.0.0.1", "[::1]"].includes(base.hostname)) {
    throw new Error("MCP HTTP bridge requires a loopback HTTP origin");
  }
  const route = tool.paidHttp;
  const method = String(route.method || "");
  if (!["GET", "POST"].includes(method) || !/^\/(?!\/)[^?#]*$/.test(route.path)) throw new Error("invalid MCP HTTP route");
  const resource = new URL(route.resourceUrl);
  if (resource.protocol !== "https:" || resource.pathname !== route.path || resource.search || resource.hash || resource.username || resource.password) {
    throw new Error("MCP HTTP bridge requires a fixed public HTTPS resource");
  }
  return async (_args, extra) => {
    const request = mcpHttpRequestAls.getStore();
    let requestPath = route.path;
    let body = null;
    if (method === "GET") {
      const bounded = boundedGetArguments(_args, route.maxRequestBytes);
      if (bounded.error) {
        return { ...asToolResult({ ok: false, error: bounded.error, charged: false }), isError: true };
      }
      requestPath = bounded.query ? `${route.path}?${bounded.query}` : route.path;
    } else {
      body = JSON.stringify(request?.body?.params?.arguments ?? _args);
      if (Buffer.byteLength(body) > route.maxRequestBytes) {
        return { ...asToolResult({ ok: false, error: "request_body_too_large", charged: false }), isError: true };
      }
    }
    const headers = { host: resource.host, "x-forwarded-proto": "https" };
    if (method === "POST") headers["content-type"] = "application/json";
    // Retain only a canonical, caller-declared source on the existing HTTP
    // writer. Never forward owner tokens, identity headers or arbitrary labels.
    const sourceHeader = request?.headers?.["x-samedaydesk-agent-source"];
    const declaredSource = typeof sourceHeader === "string" ? classifyDeclaredAgentDiscoverySource(sourceHeader) : null;
    const declaredHeader = listDeclaredAgentDiscoverySources().find(({ source }) => source === declaredSource);
    if (declaredHeader) headers["x-samedaydesk-agent-source"] = declaredHeader.value;
    for (const name of ["authorization", "payment-signature", "x-payment", "x-payment-signature"]) {
      const value = request?.headers?.[name];
      if (typeof value === "string") headers[name] = value;
    }
    const payment = extra?._meta?.[MCP_PAYMENT_META_KEY];
    if (payment) headers["payment-signature"] = Buffer.from(JSON.stringify(payment)).toString("base64");
    if (headers.authorization && (headers["payment-signature"] || headers["x-payment"] || headers["x-payment-signature"])) {
      return { ...asToolResult({ ok: false, error: "choose_one_payment_rail", charged: false }), isError: true };
    }
    for (const name of ["payment-signature", "x-payment", "x-payment-signature"]) {
      if (!headers[name]) continue;
      try {
        const credential = JSON.parse(Buffer.from(headers[name], "base64").toString("utf8"));
        if (credential.resource?.url !== `${resource.origin}${requestPath}`) throw new Error("wrong resource");
      } catch {
        return { ...asToolResult({ ok: false, error: "payment_resource_mismatch", charged: false,
          resource: resource.href }), isError: true };
      }
    }
    try {
      const response = await new Promise((resolve, reject) => {
        const req = requestHttp(new URL(requestPath, base), { method, headers,
          signal: AbortSignal.timeout(60_000) }, resolve);
        req.on("error", reject);
        req.end(body ?? undefined);
      });
      const chunks = [];
      let bytes = 0;
      for await (const part of response) {
        bytes += part.length;
        if (bytes > route.maxResponseBytes) { response.destroy(); throw new Error("HTTP bridge response exceeds ceiling"); }
        chunks.push(part);
      }
      // Use the canonical v2 offer, not the legacy discovery body (which adds
      // non-payment fields to accepts.extra and cannot be echoed as v2 terms).
      const value = response.statusCode === 402 && response.headers["payment-required"]
        ? JSON.parse(Buffer.from(response.headers["payment-required"], "base64").toString("utf8"))
        : JSON.parse(Buffer.concat(chunks).toString("utf8"));
      const publicHeaders = {};
      for (const name of ["www-authenticate", "payment-receipt", "payment-required", "payment-response"]) {
        if (typeof response.headers[name] === "string") publicHeaders[name] = response.headers[name];
      }
      // A semantic refusal is not a paid-200 body. The success outputSchema rejects
      // it, so the exact JSON stays in text and isError stays true.
      const structured = readExtractBatchInputRefusalCode(value) === null;
      const result = withoutSuccessShapedStructuredContent({ ...asToolResult(value, { structured }),
        ...(!(response.statusCode >= 200 && response.statusCode < 300) || value.error ? { isError: true } : {}),
        _meta: { "samedaydesk/http": { resource: resource.href, status: response.statusCode, headers: publicHeaders } } });
      const feedbackMeta = callerResultFeedbackMetaFromHeaders(response.headers);
      if (feedbackMeta) result._meta["samedaydesk/caller-result-feedback"] = feedbackMeta;
      const proof = response.headers["payment-response"];
      if (proof) {
        try { result._meta["x402/payment-response"] = JSON.parse(Buffer.from(proof, "base64").toString("utf8")); }
        catch { /* never fabricate settlement evidence */ }
      }
      return result;
    } catch {
      return withoutSuccessShapedStructuredContent({ ...asToolResult({ ok: false, error: "paid_http_outcome_unresolved", charged: null,
        boundary: "Do not create a replacement payment automatically. Retry only the identical authorized request." }), isError: true });
    }
  };
}

function isJsonRpcObject(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function jsonRpcHasId(body) {
  return isJsonRpcObject(body) && Object.hasOwn(body, "id");
}

function jsonRpcToolName(body) {
  const name = body?.params?.name;
  return typeof name === "string" ? name : null;
}

function isJsonRpcResponseMessage(message) {
  return (
    isJsonRpcObject(message)
    && message.jsonrpc === "2.0"
    && Object.hasOwn(message, "id")
    && (Object.hasOwn(message, "result") || Object.hasOwn(message, "error"))
    && !Object.hasOwn(message, "method")
  );
}

function isTypedPaymentRequiredResult(result) {
  if (!result || typeof result !== "object" || Array.isArray(result)) return false;
  if (result.isError !== true) return false;
  const body = result.structuredContent;
  if (!body || typeof body !== "object" || Array.isArray(body)) return false;
  return Number.isInteger(body.x402Version) && Array.isArray(body.accepts);
}

function classifyOutboundKind(message) {
  if (Object.hasOwn(message, "error")) return "transport_error";
  if (isTypedPaymentRequiredResult(message.result)) return "payment_required";
  return "tool_result";
}

function freeUnpaidHandler(tool) {
  return async (args) => {
    try {
      const value = await tool.run(args);
      const failed = !value || value.ok === false || Boolean(value.error);
      return withoutSuccessShapedStructuredContent({
        ...asToolResult(value, { structured: !failed }),
        ...(failed ? { isError: true } : {}),
      });
    } catch (error) {
      return withoutSuccessShapedStructuredContent({
        ...asToolResult({
          ok: false,
          error: String(error?.message || error),
          charged: false,
        }),
        isError: true,
      });
    }
  };
}

function baselinePaidHandler(tool) {
  return async (args) => {
    if (tool.returnMcpResult) return tool.run(args);
    try {
      return withoutSuccessShapedStructuredContent(asToolResult(await tool.run(args), { structured: Boolean(tool.outputSchema) }));
    } catch (e) {
      return withoutSuccessShapedStructuredContent({ ...asToolResult({ ok: false, error: String(e?.message || e), charged: false }), isError: true });
    }
  };
}

function observedPaidHandler(tool) {
  return async (args) => {
    const attempt = mcpTypedAttemptAls.getStore();
    attempt?.handlerStarted();
    if (tool.returnMcpResult) {
      try {
        const result = await tool.run(args);
        attempt?.handlerFinished({ isError: result?.isError === true });
        return result;
      } catch (error) {
        attempt?.handlerThrew();
        throw error;
      }
    }
    try {
      const result = withoutSuccessShapedStructuredContent(asToolResult(await tool.run(args), { structured: Boolean(tool.outputSchema) }));
      attempt?.handlerFinished({ isError: result?.isError === true });
      return result;
    } catch (e) {
      attempt?.handlerThrew();
      return withoutSuccessShapedStructuredContent({ ...asToolResult({ ok: false, error: String(e?.message || e), charged: false }), isError: true });
    }
  };
}

function registerOfficialLifecycleHooks(resourceServer) {
  resourceServer.onAfterVerify((context) => {
    const result = context?.result;
    mcpTypedAttemptAls.getStore()?.observeVerifyOutcome({
      isValid: result?.isValid === true,
      skipHandler: Boolean(result?.skipHandler),
    });
    return undefined;
  });
  resourceServer.onVerifyFailure(() => {
    mcpTypedAttemptAls.getStore()?.observeVerifyOutcome({ isValid: false });
    return undefined;
  });
  resourceServer.onAfterSettle((context) => {
    const result = context?.result;
    const requirements = context?.requirements;
    const success = result?.success === true ? true : result?.success === false ? false : undefined;
    const transaction = typeof result?.transaction === "string" ? result.transaction : undefined;
    const amount = typeof result?.amount === "string"
      ? result.amount
      : typeof requirements?.amount === "string"
        ? requirements.amount
        : null;
    mcpTypedAttemptAls.getStore()?.observeSettleOutcome({
      success,
      settlementReference: success === true ? transaction : undefined,
      facilitatorSettlement: success === true ? {
        transaction: transaction ?? null,
        network: typeof result?.network === "string" ? result.network : null,
        amount,
        asset: typeof requirements?.asset === "string" ? requirements.asset : null,
        payee: typeof requirements?.payTo === "string" ? requirements.payTo : null,
      } : null,
    });
    return undefined;
  });
  resourceServer.onSettleFailure(() => {
    mcpTypedAttemptAls.getStore()?.observeSettleOutcome({ success: false });
    return undefined;
  });
  resourceServer.onVerifiedPaymentCanceled(() => {
    mcpTypedAttemptAls.getStore()?.observeVerifiedCancellation();
    return undefined;
  });
}

function createTypedTelemetryLifecycle(onAppend, { jsonResponse = false } = {}) {
  let sealed = false;
  let failures = 0;
  const pending = new Set();

  function finishEntry(entry) {
    if (entry.finished) return;
    entry.finished = true;
    pending.delete(entry);
    entry.resolve();
  }

  function invokeUser(decision, requestAttribution, declaredSource, delivery, facilitatorSettlement, entry) {
    let assimilated;
    try {
      // Assimilate without probing result.then first: a throwing `then` accessor
      // or Proxy trap is consumed by the resolving functions as a rejection and
      // stays inside this failure-safe terminal path.
      assimilated = Promise.resolve(onAppend(decision, requestAttribution, declaredSource, delivery, facilitatorSettlement));
    } catch {
      failures += 1;
      finishEntry(entry);
      return;
    }
    assimilated.then(
      () => finishEntry(entry),
      () => {
        failures += 1;
        finishEntry(entry);
      },
    );
  }

  function schedule(decision, requestAttribution = null, declaredSource = null, delivery = null, facilitatorSettlement = null) {
    if (sealed || typeof onAppend !== "function") return;
    let resolve;
    const done = new Promise((next) => {
      resolve = next;
    });
    const entry = { done, resolve, finished: false, timer: null };
    pending.add(entry);
    const launch = () => {
      entry.timer = null;
      invokeUser(decision, requestAttribution, declaredSource, delivery, facilitatorSettlement, entry);
    };
    if (jsonResponse && decision?.result !== "paid_success") {
      queueMicrotask(launch);
      return;
    }
    entry.timer = setTimeout(launch, 8);
  }

  async function drain({ timeoutMs } = {}) {
    const inFlight = [...pending];
    if (inFlight.length === 0) {
      return { drained: true, pending: 0, failures };
    }
    const wait = Promise.all(inFlight.map((entry) => entry.done));
    const budget = Number(timeoutMs);
    if (!Number.isFinite(budget)) {
      await wait;
      return { drained: pending.size === 0, pending: pending.size, failures };
    }
    let timer;
    try {
      const timedOut = await Promise.race([
        wait.then(() => false),
        new Promise((resolve) => {
          timer = setTimeout(() => resolve(true), Math.max(0, budget));
        }),
      ]);
      const left = pending.size;
      return {
        drained: timedOut === false && left === 0,
        pending: left,
        failures,
      };
    } finally {
      clearTimeout(timer);
    }
  }

  return {
    schedule,
    flush: (options) => drain(options),
    shutdown(options) {
      sealed = true;
      return drain(options);
    },
  };
}

function sealToolResultForSend(message, attempt, callerResultFeedbackKey) {
  if (!attempt || !isJsonRpcResponseMessage(message)) return null;
  if (classifyOutboundKind(message) !== "tool_result") return null;
  try {
    const delivery = sealObservedMcpToolResult({
      tool: attempt.binding?.tool,
      productSku: attempt.binding?.productSku,
      resource: attempt.binding?.resource,
      issuedOfferDigest: attempt.binding?.issuedOfferDigest,
      callId: Object.hasOwn(message, "id") ? message.id : null,
      result: message.result,
      settlementReference: attempt.readSettlementReference?.() || null,
    });
    attachMcpCallerResultFeedback(message.result, {
      key: callerResultFeedbackKey,
      observation: delivery,
      eligible: attempt.acceptsCallerResultFeedback?.() === true,
    });
    return delivery;
  } catch {
    return null;
  }
}

function decorateTransportSend(transport, attempt, callerResultFeedbackKey = "") {
  const originalSend = transport.send;
  let used = false;
  transport.send = async function typedSend(message, options) {
    const prepared = used ? null : sealToolResultForSend(message, attempt, callerResultFeedbackKey);
    let delegateResult;
    try {
      delegateResult = await originalSend.call(this, message, options);
    } catch (error) {
      if (attempt && !used) {
        used = true;
        attempt.noteTransportError();
        attempt.finalize({ kind: "transport_error" });
      }
      throw error;
    }
    if (attempt && !used && isJsonRpcResponseMessage(message)) {
      used = true;
      const kind = classifyOutboundKind(message);
      if (kind === "tool_result") {
        try {
          if (message.result?.isError === true) attempt.overrideFinalApplicationError();
          if (prepared) attempt.noteToolDelivery(prepared);
        } catch {
          // Delivery capture must not change the MCP response.
        }
      }
      attempt.finalize({
        responseId: Object.hasOwn(message, "id") ? message.id : null,
        kind,
      });
    }
    return delegateResult;
  };
}

function createTypedAttemptForBody(body, catalog, onAppend, requestAttribution = null, declaredSource = null) {
  if (!isJsonRpcObject(body) || body.jsonrpc !== "2.0" || body.method !== "tools/call") {
    return { attempt: null };
  }
  const toolName = jsonRpcToolName(body);
  const registered = toolName ? catalog.get(toolName) : null;
  if (registered?.free === true) return { attempt: null };
  const hasId = jsonRpcHasId(body);
  const binding = registered?.binding ?? UNREGISTERED_SENTINEL_BINDING;
  const attempt = createMcpTypedTelemetryAttempt({
    binding,
    request: {
      jsonrpc: "2.0",
      hasId,
      id: hasId ? body.id : null,
      method: "tools/call",
    },
    // The inner HTTP request owns paidHttp source attribution. Preserve typed
    // diagnostics, but never attach a second source count to that same hop.
    onAppend: (decision, delivery, facilitatorSettlement) => onAppend(
      decision,
      requestAttribution,
      registered?.httpOwned ? null : declaredSource,
      registered?.httpOwned ? null : delivery,
      facilitatorSettlement,
    ),
  });
  if (!hasId) {
    attempt.finalize({ responseId: null, kind: "no_response" });
    return { attempt: null };
  }
  return { attempt };
}

/**
 * Mount a paid MCP server at POST /mcp on an existing Express app.
 *
 * @param {import('express').Express} app
 * @param {object} cfg
 * @param {object} cfg.facilitatorClient - the SAME HTTPFacilitatorClient server.js uses (CDP)
 * @param {string} cfg.network          - CAIP-2, e.g. "eip155:8453"
 * @param {string} cfg.payTo            - our wallet; USDC settles here
 * @param {{name:string,version:string}} cfg.serverInfo
 * @param {Array<{name:string,title?:string,description:string,price:string,inputSchema:Record<string,z.ZodTypeAny>,run:(args:any)=>Promise<any>,tags?:string[]}>} cfg.tools
 * @returns {Promise<{toolCount:number}>}
 */
export async function mountMcp(app, {
  facilitatorClient,
  network,
  payTo,
  serverInfo,
  tools,
  typedTelemetry = null,
  streamableHttpOptions = undefined,
  configureResourceServer = null,
  httpBaseUrl = null,
  callerResultFeedbackKey = "",
  // Inject the existing HTTP replay journal. No second store or automatic
  // task backend is constructed by this optional native-result port.
  nativeRecovery = null,
} = {}) {
  const recoveryJournal = nativeRecovery?.journal;
  const recoveryScope = nativeRecovery ? {
    endpointUrl: nativeRecovery.endpointUrl,
    tenantId: nativeRecovery.tenantId,
  } : null;
  const recoveryProfile = nativeRecovery ? recoveryJournal?.mcpRecoveryProfile(recoveryScope) : null;
  if (nativeRecovery && (!recoveryProfile || typeof recoveryJournal.runMcpTool !== "function"
    || typeof recoveryJournal.recoverMcpResult !== "function")) throw new Error("native_recovery_journal_required");
  const typedEnabled = typedTelemetry?.enabled === true;
  const jsonResponse = streamableHttpOptions?.enableJsonResponse === true;
  const typedLifecycle = typedEnabled
    ? createTypedTelemetryLifecycle(typedTelemetry.onAppend, { jsonResponse })
    : null;
  const onAppend = typedLifecycle
    ? (decision, requestAttribution, declaredSource, delivery, facilitatorSettlement) => typedLifecycle.schedule(
      decision,
      requestAttribution,
      declaredSource,
      delivery,
      facilitatorSettlement,
    )
    : undefined;
  const paidTools = tools.filter((tool) => tool?.free !== true);
  const freeTools = tools.filter((tool) => tool?.free === true);
  const catalogByName = buildRegisteredCatalog(paidTools);
  for (const tool of freeTools) {
    if (!tool?.name || catalogByName.has(tool.name)) {
      throw new Error(`free MCP tool collides with a paid tool: ${tool?.name || "unnamed"}`);
    }
    catalogByName.set(tool.name, {
      tool: tool.name,
      productSku: `samedaydesk-${String(tool.name).replaceAll("_", "-")}`,
      resource: `mcp://tool/${tool.name}`,
      free: true,
      binding: null,
      httpOwned: false,
    });
  }

  // Dedicated resource server for MCP, sharing the facilitator with the HTTP routes.
  const resourceServer = new x402ResourceServer(nativeRecovery
    ? trackReplaySettlementAttempts(facilitatorClient) : facilitatorClient).register(network, new ExactEvmScheme());
  await resourceServer.initialize();
  if (typeof configureResourceServer === "function") {
    await configureResourceServer(resourceServer);
  }
  if (typedEnabled) registerOfficialLifecycleHooks(resourceServer);

  // Pre-build the paid wrapper for each tool ONCE (buildPaymentRequirements is async).
  const prepared = [];
  for (const t of paidTools) {
    const registered = catalogByName.get(t.name);
    const accepts = await resourceServer.buildPaymentRequirements({
      scheme: "exact",
      network,
      payTo,
      price: t.price,
    });
    const issuedOfferDigest = digestIssuedOffer(accepts, registered);
    if (!issuedOfferDigest) {
      throw new Error(`issued offer digest missing for registered tool ${t.name}`);
    }
    const binding = Object.freeze({
      tool: registered.tool,
      productSku: registered.productSku,
      resource: registered.resource,
      issuedOfferDigest,
    });
    catalogByName.set(t.name, { ...registered, binding, issuedOfferDigest, httpOwned: Boolean(t.paidHttp) });
    const paid = createPaymentWrapper(resourceServer, {
      accepts,
      resource: {
        url: resourceForTool(t.name),
        description: t.description,
        mimeType: "application/json",
        serviceName: serverInfo.name,
        tags: t.tags,
      },
    });
    // paid(handler) -> MCP tool callback (args, extra) that verifies payment (from
    // extra._meta), runs the handler, then settles. We catch handler errors and return
    // a structured ok:false so a paid call never yields an opaque failure.
    const inner = t.paidHttp ? httpRouteToolHandler(t, httpBaseUrl)
      : paid(typedEnabled ? observedPaidHandler(t) : baselinePaidHandler(t));
    const recoverable = nativeRecovery && !t.paidHttp ? async (args, extra) => {
      const request = mcpHttpRequestAls.getStore();
      return recoveryJournal.runMcpTool({ name: t.name,
        arguments: request?.body?.params?.arguments ?? args,
        payment: extra?._meta?.[MCP_PAYMENT_META_KEY], scope: recoveryScope }, () => inner(args, extra));
    } : inner;
    const revived = withRevivedArgs(recoverable, t.inputSchema);
    const handler = typedEnabled
      ? async (args, extra) => {
        const attempt = mcpTypedAttemptAls.getStore();
        if (!t.paidHttp) attempt?.markPaidWrapperEntered();
        if (attempt && extra && Object.hasOwn(extra, "requestId")) {
          attempt.bindRequestId(extra.requestId);
        }
        const result = await revived(args, extra);
        if (!t.paidHttp && attempt && !isTypedPaymentRequiredResult(result) && result?.isError !== true) {
          attempt.maybeReplayConfirmed();
        }
        return result;
      }
      : revived;
    prepared.push({
      name: t.name,
      title: t.title,
      description: t.paidHttp ? `${t.description} Payment challenge and credentials are bound to ${t.paidHttp.resourceUrl}, not mcp://. Retry the identical authorized arguments and credential.` : t.description,
      inputSchema: t.inputSchema,
      outputSchema: t.outputSchema,
      paymentMeta: createX402ToolMeta(accepts),
      inputRefusalMeta: t.inputRefusalMeta,
      guardedHttpInput: Boolean(t.paidHttp && t.inputRefusalMeta),
      operationIdentity: t.operationIdentity,
      recoveryProfile: nativeRecovery && !t.paidHttp ? recoveryProfile : null,
      handler,
      binding,
    });
  }
  for (const tool of freeTools) {
    prepared.push({
      name: tool.name,
      title: tool.title,
      description: tool.description,
      inputSchema: tool.inputSchema,
      outputSchema: tool.outputSchema,
      free: true,
      paymentMeta: { samedaydesk: { charged: false, paymentRequired: false } },
      handler: freeUnpaidHandler(tool),
      binding: null,
    });
  }
  if (nativeRecovery) {
    if (catalogByName.has(MCP_RECOVERY_TOOL)) throw new Error("native_recovery_tool_collision");
    const nativeTools = new Set(paidTools.filter(tool => !tool.paidHttp).map(tool => tool.name));
    catalogByName.set(MCP_RECOVERY_TOOL, { tool: MCP_RECOVERY_TOOL, free: true, binding: null });
    prepared.push({
      name: MCP_RECOVERY_TOOL, free: true,
      description: "Read the stored outcome of an earlier native paid call using its original input and credential. This call cannot execute or pay.",
      inputSchema: { name: z.string(), arguments: z.record(z.any()) },
      paymentMeta: { samedaydesk: { charged: false, paymentRequired: false } },
      handler: async (args, extra) => {
        if (!nativeTools.has(args.name)) return { ...asToolResult({ ok: false, error: "recovery_tool_rejected", charged: false }), isError: true };
        return recoveryJournal.recoverMcpResult({ name: args.name, arguments: args.arguments,
          payment: extra?._meta?.[MCP_PAYMENT_META_KEY], scope: recoveryScope });
      },
      binding: null,
    });
  }

  // A fresh MCP server per request (stateless mode requires server+transport per call).
  const makeServer = (requestBody) => {
    const server = new McpServer(serverInfo);
    for (const t of prepared) {
      const operationMeta = t.operationIdentity
        ? { samedaydesk: { operation: t.operationIdentity } }
        : {};
      if (t.recoveryProfile) operationMeta.samedaydesk = {
        ...operationMeta.samedaydesk, recovery: t.recoveryProfile,
      };
      // This call's original ALS arguments go unchanged to the HTTP guard.
      // Let that guard produce static refusals rather than SDK/Zod value echoes.
      // Discovery and every other call retain their advertised input schema.
      const guardedCall = t.guardedHttpInput && requestBody?.jsonrpc === "2.0"
        && requestBody?.method === "tools/call" && requestBody?.params?.name === t.name;
      server.registerTool(t.name, {
        title: t.title,
        description: t.description,
        inputSchema: guardedCall ? z.object(t.inputSchema).passthrough().catch({}) : t.inputSchema,
        outputSchema: t.outputSchema,
        _meta: { ...t.paymentMeta, ...operationMeta, ...(t.inputRefusalMeta || {}) },
      }, t.handler);
    }
    return server;
  };

  const transportOptions = {
    ...(streamableHttpOptions && typeof streamableHttpOptions === "object" ? streamableHttpOptions : {}),
    sessionIdGenerator: undefined,
  };

  // Stateless streamable-HTTP transport. express.json() scoped to this route only.
  app.post("/mcp", express.json({ limit: "1mb" }), async (req, res) => {
    injectPaymentSignatureHeader(req);
    let requestAttribution = null;
    let declaredSource = null;
    if (typedEnabled && typeof typedTelemetry?.attributionForRequest === "function") {
      try {
        requestAttribution = typedTelemetry.attributionForRequest(req);
      } catch {
        requestAttribution = null;
      }
    }
    if (typedEnabled && typeof typedTelemetry?.declaredSourceForRequest === "function") {
      try {
        const reduced = typedTelemetry.declaredSourceForRequest(req);
        declaredSource = typeof reduced === "string" ? reduced : null;
      } catch {
        declaredSource = null;
      }
    }
    const created = typedEnabled
      ? createTypedAttemptForBody(req.body, catalogByName, onAppend, requestAttribution, declaredSource)
      : { attempt: null };
    const unknownTool = unknownRegisteredToolError(req.body, catalogByName);
    if (unknownTool) {
      if (created.attempt) {
        created.attempt.finalize({
          responseId: Object.hasOwn(req.body, "id") ? req.body.id : null,
          kind: "transport_error",
        });
      }
      res.set("Cache-Control", "no-store");
      return res.status(200).json(unknownTool);
    }
    const server = makeServer(req.body);
    const transport = new StreamableHTTPServerTransport(transportOptions);
    if (created.attempt) decorateTransportSend(transport, created.attempt, callerResultFeedbackKey);
    res.on("close", () => {
      try { transport.close(); } catch { /* noop */ }
      try { server.close?.(); } catch { /* noop */ }
    });
    const run = async () => {
      try {
        await server.connect(transport);
        await transport.handleRequest(req, res, req.body);
      } catch (e) {
        created.attempt?.noteTransportError();
        if (!res.headersSent) {
          res.status(500).json({ jsonrpc: "2.0", error: { code: -32603, message: String(e?.message || e) }, id: null });
        }
      }
    };
    if (created.attempt) {
      await mcpHttpRequestAls.run(req, () => mcpTypedAttemptAls.run(created.attempt, run));
      return;
    }
    await mcpHttpRequestAls.run(req, run);
  });

  // Stateless server: no standalone GET (SSE) or DELETE (session teardown) support.
  const methodNotAllowed = (_req, res) =>
    res.status(405).json({ jsonrpc: "2.0", error: { code: -32000, message: "Method not allowed: this MCP server is stateless; POST JSON-RPC to /mcp." }, id: null });
  app.get("/mcp", methodNotAllowed);
  app.delete("/mcp", methodNotAllowed);

  const mountResult = {
    toolCount: prepared.filter((tool) => tool.free !== true).length,
    freeToolCount: prepared.filter((tool) => tool.free === true).length,
    catalog: Object.freeze(Object.fromEntries(
      [...catalogByName.entries()].map(([name, entry]) => [name, entry.binding]),
    )),
  };
  if (typedLifecycle) {
    mountResult.typedTelemetryLifecycle = {
      flush: (options) => typedLifecycle.flush(options),
      shutdown: (options) => typedLifecycle.shutdown(options),
    };
  }
  return mountResult;
}

export function mcpCallArguments(fallback) {
  const request = mcpHttpRequestAls.getStore();
  const raw = request?.body?.params?.arguments;
  if (raw && typeof raw === "object" && !Array.isArray(raw)) return raw;
  return fallback && typeof fallback === "object" && !Array.isArray(fallback) ? fallback : {};
}

export { mcpTypedAttemptAls, productSkuForTool, resourceForTool };

